package dev.pxxl;import java.util.Map;import org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.web.bind.annotation.*;@SpringBootApplication@RestController public class Application{@GetMapping("/")Map<String,String>root(){return Map.of("service","Pxxl Spring API");}@GetMapping("/health")Map<String,String>health(){return Map.of("status","ok");}@GetMapping("/api")Map<String,String>api(){return Map.of("message","Hello from Spring");}public static void main(String[]args){SpringApplication.run(Application.class,args);}}
